cd /testbed && python -c "
import astroid
code = '''import abc
from abc import ABC
X = ...  # type: abc.ABC
Y = ...  # type: ABC'''
module = astroid.parse(code)
for node in module.nodes:
    if hasattr(node, 'type_comment'):
        print(f'Node {type(node).__name__}: type_comment = {getattr(node, \"type_comment\", \"None\")}')
    if hasattr(node, 'value') and hasattr(node.value, 'type_comment'):
        print(f'Value node {type(node.value).__name__}: type_comment = {getattr(node.value, \"type_comment\", \"None\")}')
    if hasattr(node, 'targets'):
        for target in node.targets:
            print(f'Target {type(target).__name__}: {target}')
"

